// Production estimates reuse the current calculation, archive and record synchronization.
const PRODUCTION_KEY='izdelie-production-catalog-v1';
const productionScopes={product_design:'Проектирование',product_manufacturing:'Изготовление',inhouse_assembly_and_finishing:'Сборка и отделка',packaging:'Упаковка',site_installation:'Монтаж на объекте',construction:'Строительные работы',external_subcontract:'Подряд',procurement_materials:'Материалы'};
const productionMethods={direct_unit_rate:'Объём × ставка',output_per_hour:'По выработке',crew_cycle:'Цикл бригады',person_hours:'Человеко-часы',machine_hours:'Машино-часы',operator_support:'Сопровождение ЧПУ',setup_per_batch:'Наладка партии',unique_program_prep:'Уникальная программа',composite:'Комплекс / состав',external_quote:'Предложение подрядчика',manual:'Ручная ставка',panel_saw:'Карта форматника'};
const productionStatus={confirmed:'Подтверждено',preliminary:'Предварительно',missing:'Нет данных',needs_review:'Требует проверки',inactive:'Неактивно',out_of_scope:'Вне сметы'};
const productionOrigin={dialogue:'Решение из диалога',model:'Назначено моделью · предварительно',catalog:'Исходный справочник',input:'Ввод для заказа'};
let productionDraft=null,productionChoices=[],productionMigration=null,productionNeedsRecovery=false,productionDraggedId=null;
const productionGroupOpen=new Map();
function productionDefinitions(){const custom=readJSON(PRODUCTION_KEY,{});ProductionModelCore.catalogDefinitions(custom);const values=new Map(PRODUCTION_CATALOG.operations.map(d=>[d.id,d]));for(const [id,d]of Object.entries(custom))values.set(id,d);for(const d of PRODUCTION_CATALOG.operations)if(d.code==='Р128.3D'||d.pricing?.market_includes_operator||d.pricing?.pass_rate_per_pass)values.set(d.id,d);return [...values.values()];}
function productionBadge(){return '';}
function productionMoney(v){return Number.isFinite(v)?new Intl.NumberFormat('ru-RU',{minimumFractionDigits:2,maximumFractionDigits:2}).format(v)+' ₽':'Не определено';}
function productionComponentsHTML(components){if(!components?.length)return '';return '<table><thead><tr><th>Состав затрат</th><th>Себестоимость</th></tr></thead><tbody>'+components.map(c=>'<tr><td>'+esc(c.name||'Ресурс')+'</td><td>'+productionMoney(c.plannedCost)+'</td></tr>').join('')+'</tbody></table>';}
function productionMapLegacy(index){try{productionDraft=ProductionModelCore.migrate(state,productionDefinitions()).lines[index];productionEditor();}catch(e){toast(e.message);}}
function productionAddCatalogWork(record){const matches=productionDefinitions().filter(d=>d.source_record===record.id&&!['inactive','out_of_scope'].includes(d.status));if(matches.length===1){productionChoices=matches;productionChoose(0);}else if(matches.length){productionCatalog();$('production-search').value=String(record.row||'');productionCatalogResults();}else if(/^Перечень_работ:/.test(record.id))toast('Эта исходная работа исключена из активной производственной модели');else{const legacy=lineFrom(record);productionDraft=ProductionModelCore.migrate({...state,lines:[legacy]},productionDefinitions()).lines[0];productionEditor();}}
function productionUnmappedHTML(){const lines=state.lines.map((l,index)=>({l,index})).filter(({l})=>l.kind==='work'&&!l.production);return lines.length?'<div class="card"><h2>Работы, требующие сопоставления</h2>'+lines.map(({l,index})=>'<div class="metricline"><span>'+esc(l.name)+'</span><button onclick="productionMapLegacy('+index+')">Сопоставить и проверить</button><button onclick="productionRemove('+index+')">Удалить</button></div>').join('')+'</div>':'';}
function productionSyncOperatorSupport(next){
 if(next.engineVersion!==ProductionModelCore.VERSION)return;
 const key=l=>[l.production.productId,l.production.workPackage,l.production.segment,l.production.definition.post_id].join('\u001f'),definitions=productionDefinitions();
 const supportFor=post=>definitions.find(d=>d.post_id===post&&(d.calculation_method==='operator_support'||post==='P43'&&d.code==='ФРС.ОП'));
 const machines=next.lines.filter(l=>l.production&&ProductionModelCore.operatorSource(l.production.definition)&&!['inactive','out_of_scope'].includes(l.production.definition.status)&&supportFor(l.production.definition.post_id));
 next.lines=next.lines.filter(l=>!l.production?.autoSupport||machines.some(m=>key(m)===key(l)));
 for(const machine of machines){
  const source=supportFor(machine.production.definition.post_id);
  if(machine.production.selected===false||next.lines.some(l=>l.production&&(l.production.definition.calculation_method==='operator_support'||l.production.definition.code===source.code)&&key(l)===key(machine)))continue;
  const d=structuredClone(source);if(d.post_id==='P43'){d.calculation_method='operator_support';d.resource_type='operator_support';}
  const p=machine.production;next.lines.push(ProductionModelCore.makeLine(d,uid(),{quantity:null},{productId:p.productId,workPackage:p.workPackage,segment:p.segment,autoSupport:true}));
 }
}
function productionStore(next){try{productionSyncOperatorSupport(next);DomainSchema.calculation(next);localStorage.setItem('izdelie-state',JSON.stringify(next));state=next;persist();return true;}catch(e){toast('Изменения не применены: '+e.message);return false;}}
function productionSyncMarketStations(next){if(next.engineVersion!==ProductionModelCore.VERSION)return false;const latest=new Map(productionDefinitions().filter(d=>d.code==='Р128.3D'||d.pricing?.market_includes_operator||d.pricing?.pass_rate_per_pass).map(d=>[d.code,d])),changed=[];for(const l of next.lines||[]){const d=l.production?.definition,source=d&&latest.get(d.code);if(!source)continue;const milling=source.pricing?.pass_rate_per_pass,updated3d=source.code==='Р128.3D',unchanged=updated3d?d.parameters?.machine_hours_per_unit?.value===source.parameters?.machine_hours_per_unit?.value&&d.parameters?.cost_per_machine_hour?.value===source.parameters?.cost_per_machine_hour?.value:milling?d.pricing.current_unit_price===source.pricing.current_unit_price&&d.parameters?.output_per_hour?.value===source.parameters?.output_per_hour?.value:d.pricing.current_unit_price===source.pricing.current_unit_price&&d.pricing.market_unit_price===source.pricing.market_unit_price;if(unchanged)continue;d.pricing=structuredClone(source.pricing);d.parameters=structuredClone(source.parameters);d.cost_model=structuredClone(source.cost_model);d.unit=source.unit;l.price=source.pricing.current_unit_price;l.basePrice=source.pricing.base_unit_price;changed.push(l.id);}return changed.length?productionStore(next):false;}
function productionEnable(){try{productionMigration=ProductionModelCore.migrate(state,productionDefinitions());const before=CostEngine.calculate(state),after=CostEngine.calculate(productionMigration);modal('Новая производственная методика',`<p>Будет создана рабочая копия. Предыдущий расчёт останется доступен через «Восстановить предыдущий расчёт» в базе изделий.</p><p>Тарифная база и плановые затраты разделены. Итог заказа: сумма выбранных позиций × 1,40. Старые проценты накладных, транспорта и НДС не переносятся в новую формулу. При необходимости эти затраты вводятся отдельными обоснованными строками.</p><div class="grid2"><div>Текущий итог: <b>${productionMoney(before.total)}</b></div><div>Предпросмотр нового: <b>${productionMoney(after.total)}</b></div></div><p>Материалы сохраняются. Перенесённые работы требуют проверки варианта, единицы и плановой себестоимости. Архивные версии и КП сохраняются.</p><div class="mini-actions"><button class="primary" onclick="productionApplyMigration()">Создать копию по новой методике</button><button onclick="$('modal').close()">Отмена</button></div>`);}catch(e){toast(e.message);}}
function productionApplyMigration(){if(!productionMigration)return;if(!keepCurrent())return;if(productionStore(productionMigration)){productionMigration=null;$('modal').close();go(2);}}
function productionCatalog(){const values=productionDefinitions();modal('Выбрать операцию',`<div class="grid2"><div class="field"><label for="production-search">Название операции</label><input id="production-search" oninput="productionCatalogResults()" placeholder="Найти работу"></div><div class="field"><label for="production-shop">Цех</label><select id="production-shop" onchange="productionCatalogPosts()"><option value="">Все цеха</option>${[...new Set(values.map(d=>d.shop_id))].map(x=>'<option>'+esc(x)+'</option>').join('')}</select></div><div class="field"><label for="production-post">Пост</label><select id="production-post" onchange="productionCatalogResults()"><option value="">Все посты</option></select></div><div class="field"><label for="production-scope">Область работ</label><select id="production-scope" onchange="productionCatalogResults()"><option value="">Все области</option>${Object.entries(productionScopes).map(([k,v])=>'<option value="'+k+'" '+(page===19&&k==='site_installation'?'selected':'')+'>'+v+'</option>').join('')}</select></div></div><div id="production-catalog-results"></div><details><summary>Настройки справочника</summary><div class="mini-actions"><button onclick="productionNewOperation()">＋ Своя операция</button><button onclick="productionDeck()">Детализация настила</button><button onclick="productionExportDefinitions()">Экспорт настроек</button><label class="textbutton">Импорт настроек<input type="file" accept=".json" onchange="productionImportDefinitions(event)"></label></div></details>`);productionCatalogPosts();}
function productionCatalogPosts(){const shop=$('production-shop').value;$('production-post').innerHTML='<option value="">Все посты</option>'+[...new Set(productionDefinitions().filter(d=>!shop||d.shop_id===shop).map(d=>d.post_id).filter(Boolean))].sort().map(p=>'<option value="'+esc(p)+'">'+esc(productionPostName(p))+'</option>').join('');productionCatalogResults();}
function productionCatalogResults(){const query=$('production-search').value.toLocaleLowerCase('ru'),shop=$('production-shop').value,post=$('production-post').value,scope=$('production-scope').value;productionChoices=productionDefinitions().filter(d=>!['inactive','out_of_scope'].includes(d.status)&&(!shop||d.shop_id===shop)&&(!post||d.post_id===post)&&(!scope||d.scope===scope)&&[productionDisplayName(d),productionPostName(d.post_id),String(d.source_work_id??'')].join(' ').toLocaleLowerCase('ru').includes(query));$('production-catalog-results').innerHTML='<p class="small">Найдено: '+productionChoices.length+'</p><div class="tablewrap"><table><thead><tr><th>Операция</th><th>Цех / пост</th><th>Себестоимость единицы</th><th></th></tr></thead><tbody>'+productionChoices.map((d,i)=>'<tr><td>'+esc(productionDisplayName(d))+'</td><td>'+esc(d.shop_id)+'<span class="source">'+esc(productionPostName(d.post_id))+'</span></td><td>'+(d.calculation_method==='panel_saw'?'По карте раскроя':productionMoney(ProductionModelCore.resourceUnitCost(d))+' / '+esc(MaterialCore.unitLabel(d.unit)))+'</td><td><button onclick="productionChoose('+i+')">Выбрать</button></td></tr>').join('')+'</tbody></table></div>';}
function productionExportDefinitions(){download('Производственные_операции_настройки.json',JSON.stringify({format:'izdelie-production-catalog',version:1,operations:readJSON(PRODUCTION_KEY,{})},null,2),'application/json');}
async function productionImportDefinitions(event){try{const file=event.target.files[0];if(!file||file.size>1500000)throw Error('Выберите JSON настроек до 1,5 МБ');const parsed=JSON.parse(await file.text());if(parsed.format!=='izdelie-production-catalog'||parsed.version!==1)throw Error('Неизвестный формат настроек');const incoming=ProductionModelCore.catalogDefinitions(parsed.operations),current=readJSON(PRODUCTION_KEY,{});if(parsed.source_sync===true)for(const [id,d]of Object.entries(incoming))if(current[id]){incoming[id]=ProductionModelCore.synchronize(current[id],{unit:d.unit,formula:d.pricing.source_formula,parameters:d.pricing.source_parameters});incoming[id].source_name=d.source_name;}const next={...current,...incoming};ProductionModelCore.catalogDefinitions(next);modal('Проверка настроек операций','<p>Проверено операций: '+Object.keys(incoming).length+'. Совпадающие коды обновят справочник. Уже сохранённые строки заказов сохранят свои ставки и нормы.</p><p>Изменённые исходные единицы отмечены предупреждением до сохранения настройки.</p><button id="production-import-apply" class="primary">Применить настройки</button>');$('production-import-apply').onclick=()=>{if(!writeJSON('izdelie-production-catalog-recovery-v1',current))return;if(writeJSON(PRODUCTION_KEY,next))productionCatalog();};}catch(e){toast('Файл не применён: '+e.message);}}
function productionChoose(index){const d=productionChoices[index];if(!d)return;const inputs=d.calculation_method==='panel_saw'?{quantity:1,card:{rows:[],setups:null,helper_hours:0,map_hours:0},panel_parameters:structuredClone(PRODUCTION_CATALOG.panelSaw)}:{quantity:null};if(d.code==='Р144.П'){inputs.package_cut=true;inputs.profiles_per_package=null;}productionDraft=ProductionModelCore.makeLine(d,uid(),inputs,{productId:state.name||'Изделие'});productionNeedsRecovery=false;productionEditor();}
function productionNewOperation(){const id=uid(),sample=productionDefinitions().find(d=>page===19?d.scope==='site_installation':d.post_id==='P28');const d={id,code:'СВОЯ-'+id.slice(0,8),source_work_id:null,name:'Новая операция',scope:sample?.scope||'product_manufacturing',stage:sample?.stage||'machining',shop_id:sample?.shop_id||'Сборочный',post_id:sample?.post_id||null,unit:'шт.',quantity_basis:'Количество выполненных единиц',financial_basis:'Параметры собственной операции',calculation_method:'direct_unit_rate',origin:'input',status:'needs_review',resource_costing:true,pricing:{base_unit_price:null,current_unit_price:null,manual_override:false,source_formula:'',source_parameters:{}},cost_model:{unit_cost:null},parameters:{person_hours_per_unit:{value:null},cost_per_person_hour:{value:null},machine_hours_per_unit:{value:0},cost_per_machine_hour:{value:0},supplies_or_purchased_cost_per_unit:{value:0}}};productionDraft=ProductionModelCore.makeLine(d,uid(),{quantity:null},{productId:state.name||'Изделие'});productionNeedsRecovery=false;productionEditor();}
function productionEdit(index){productionRememberGroups();const l=state.lines[index];if(!l?.production)return;productionDraft=structuredClone(l);productionNeedsRecovery=false;productionEditor();}
function productionField(key,label,value,type='text',extra=''){return '<div class="field"><label for="pr-'+key+'">'+label+'</label><input id="pr-'+key+'" type="'+type+'" value="'+esc(value??'')+'" '+(type==='number'?'min="0" step="any" ':'')+extra+'></div>';}
function productionSelect(key,label,value,options){return '<div class="field"><label for="pr-'+key+'">'+label+'</label><select id="pr-'+key+'">'+Object.entries(options).map(([k,v])=>'<option value="'+esc(k)+'" '+(k===value?'selected':'')+'>'+esc(v)+'</option>').join('')+'</select></div>';}
function productionEditor(){const l=productionDraft,p=l.production,d=p.definition,i=p.inputs,method=d.calculation_method,n=productionField,fixed=productionFixed(d),location=productionLocation(d);let top='',fields='';
 if(method==='panel_saw'){top='<p class="production-volume-heading">Карта раскроя · объём на весь заказ</p>';fields=productionSawFields(i);}
 else if(method==='operator_support'){top='<p class="production-volume-heading">Объём сопровождения — по работам поста · чел·ч</p>';fields=n('person_hours','Человеко-часы (пусто — по работам поста или занятости)',i.person_hours,'number')+n('machine_hours','Машино-часы (пусто — автоматически по работам поста)',i.machine_hours,'number')+(d.post_id==='P08'?productionSelect('mode','Режим для ручных машино-часов',i.mode||'flat',{flat:'Плоская фрезеровка','3d':'3D-фрезеровка'}):'')+'<details><summary>Фактическая занятость вместо нормы</summary><div class="field"><label for="pr-intervals">Сотрудник; начало; конец — по одной записи в строке</label><textarea id="pr-intervals">'+esc((i.intervals||[]).map(x=>x.employee+'; '+x.start+'; '+x.end).join('\n'))+'</textarea><p class="small">Время в минутах от общего начала заказа. Пересечения одного сотрудника учитываются один раз.</p></div></details>';}
 else if(method==='setup_per_batch'){top=n('setup_hours','Время наладки партии, ч',i.setup_hours,'number');fields=n('batch_id','Обозначение партии',i.batch_id||'Партия 1');}
 else{top='<div class="production-volume">'+n('quantity',(l.scope==='unit'?'Объём на изделие, ':'Объём для всего заказа, ')+MaterialCore.unitLabel(d.unit),i.quantity,'number')+'<span>'+esc(MaterialCore.unitLabel(d.unit))+'</span></div>';if(method==='unique_program_prep')fields=n('unique_program_id','Обозначение уникального комплекта',i.unique_program_id||'Основной');}
 if(d.source_work_id===144)fields+='<label class="check"><input id="pr-package_cut" type="checkbox" '+(i.package_cut?'checked':'')+'> Пакетный распил</label>'+n('profiles_per_package','Профилей в пакете (целое от 2)',i.profiles_per_package,'number');
 const labor=(d.parameters?.person_hours_per_unit?.value||0)>0||['crew_cycle','person_hours','setup_per_batch','operator_support','unique_program_prep'].includes(method);
 if(labor)fields+=n('labor_factor','Множитель трудозатрат',i.labor_factor??1,'number','aria-describedby="pr-factor-help"')+'<p id="pr-factor-help" class="small">1 — обычные условия; 1,2 — увеличение трудовой части на 20%. На станок и расходники не влияет.</p>';
 let custom='';if(!fixed){custom='<div class="grid2">'+n('name','Название операции',d.name)+n('unit','Единица объёма',d.unit)+productionSelect('assignment','Цех и пост',d.shop_id+'|'+(d.post_id||''),productionAssignmentOptions())+'</div><details><summary>Параметры собственной операции</summary><div class="grid2">'+Object.entries({person_hours_per_unit:'Трудозатраты на единицу, чел·ч',cost_per_person_hour:'Стоимость часа труда, ₽/чел·ч',machine_hours_per_unit:'Работа станка на единицу, маш·ч',cost_per_machine_hour:'Стоимость часа станка, ₽/маш·ч',supplies_or_purchased_cost_per_unit:'Расходники на единицу, ₽'}).map(([key,label])=>n('resource-'+key,label,d.parameters?.[key]?.value,'number')).join('')+n('price','Внутренний тариф единицы для продажи, ₽',d.pricing.current_unit_price,'number')+'</div></details>';}
 const sourceAvailable=productionSourceDefinitions().length&&(!d.resource_costing||d.unit_change_notice||d.migration_note);
 modal(productionDisplayName(d),`<form onsubmit="productionCommit(event)"><div id="production-form-error" class="warning" role="alert" tabindex="-1"></div>${top}<div class="production-attributes"><span>${esc(location.shop_id)}</span><span>${esc(productionPostName(location.post_id))}</span><span>${esc(productionScopes[d.scope])}</span></div>${productionNeedsRecovery?'<p class="note info">Будут применены исходные нормы. Укажите объём в показанной единице; предыдущий заказ сохранится для восстановления.</p>':''}${sourceAvailable?'<p><button type="button" onclick="productionSourceChoices()">Посмотреть и применить исходную методику</button></p>':''}${custom}${fields}<details><summary>Ценообразование</summary><h3>Расчёт себестоимости</h3>${productionCostDetails(l)}${d.calculation_method==='panel_saw'?productionSawNorms(i.panel_parameters):''}</details><details><summary>Изделие и участок</summary><div class="grid2">${n('product','Изделие / узел',p.productId)}${n('segment','Физический участок',p.segment)}</div>${productionSelect('parent','Включить в комплекс',p.parentLineId||'',Object.fromEntries([['','Самостоятельная операция'],...state.lines.filter(x=>x.id!==l.id&&x.production?.definition.calculation_method==='composite').map(x=>[x.id,productionDisplayName(x.production.definition)])]))}</details>${!fixed?'<label class="check"><input id="pr-save_definition" type="checkbox"> Сохранить собственную операцию в справочник</label>':''}<div class="mini-actions"><button class="primary" type="submit">Применить к заказу</button><button type="button" onclick="productionPreview()">Проверить расчёт</button><button type="button" onclick="$('modal').close()">Отмена</button></div><div id="production-preview" aria-live="polite"></div></form>`);
}
function productionReadDraft(){const next=structuredClone(productionDraft),p=next.production,d=p.definition,i=p.inputs,get=k=>document.getElementById('pr-'+k),str=k=>get(k)?.value??'',num=k=>str(k)===''?null:Number(str(k));
 if(!productionFixed(d)){for(const k of ['name','unit'])if(get(k))d[k]=str(k).trim();if(get('assignment')){const sample=productionDefinitions().find(x=>x.shop_id+'|'+(x.post_id||'')===str('assignment'));if(sample)for(const key of ['shop_id','post_id','scope','stage'])d[key]=sample[key];}for(const k of ['person_hours_per_unit','cost_per_person_hour','machine_hours_per_unit','cost_per_machine_hour','supplies_or_purchased_cost_per_unit'])if(get('resource-'+k)){d.parameters??={};d.parameters[k]={value:num('resource-'+k),origin:'input'};}if(get('price'))d.pricing.current_unit_price=d.pricing.base_unit_price=num('price');d.cost_model.unit_cost=ProductionModelCore.resourceUnitCost(d);}
 for(const [field,key]of [['product','productId'],['segment','segment']])if(get(field))p[key]=str(field).trim();if(get('parent')){if(str('parent'))p.parentLineId=str('parent');else delete p.parentLineId;}
 for(const k of ['quantity','person_hours','machine_hours','setup_hours','profiles_per_package','labor_factor'])if(get(k))i[k]=num(k);for(const k of ['batch_id','unique_program_id','mode'])if(get(k))i[k]=str(k);if(get('package_cut'))i.package_cut=get('package_cut').checked;
 if(get('quantity')&&d.calculation_method==='person_hours'&&Object.hasOwn(i,'person_hours'))i.person_hours=i.quantity;if(get('quantity')&&d.calculation_method==='machine_hours'&&!d.productivity)i.machine_hours=i.quantity;
 if(get('intervals'))i.intervals=str('intervals').trim()?str('intervals').split('\n').filter(x=>x.trim()).map(row=>{const parts=row.split(';').map(s=>s.trim());if(parts.length!==3||!parts[1]||!parts[2])throw Error('Интервалы: сотрудник; начало; конец');return {employee:parts[0],start:Number(parts[1]),end:Number(parts[2])}}):[];
 if(d.calculation_method==='panel_saw')productionReadSaw(i);
 Object.assign(next,{name:d.name,unit:d.unit,group:d.shop_id,price:ProductionModelCore.price(d.pricing.current_unit_price),basePrice:d.pricing.base_unit_price,qty:i.quantity??(d.calculation_method==='panel_saw'?1:null),source:d.financial_basis,costCategory:d.scope==='site_installation'?'installation':d.scope==='product_design'?'design':'production'});return next;
}
function productionFormError(e){$('production-form-error').textContent=e.message;$('production-form-error').focus();}
function productionPreview(){try{const l=productionReadDraft(),next=structuredClone(state),index=next.lines.findIndex(x=>x.id===l.id);if(index<0)next.lines.push(l);else next.lines[index]=l;productionSyncOperatorSupport(next);const r=ProductionModelCore.calculate(next),row=r.rows.find(x=>x.id===l.id);$('production-preview').innerHTML='<p>Себестоимость операции: <b>'+productionMoney(row?.plannedCost)+'</b></p>'+productionComponentsHTML(row?.components)+(r.errors.length?'<p>'+r.errors.map(esc).join('<br>')+'</p>':'');}catch(e){productionFormError(e);}}
function productionCommit(event){event.preventDefault();try{const l=productionReadDraft(),p=l.production;p.definition=ProductionModelCore.saveConfiguration(p.definition);ProductionModelCore.metadata({...state,lines:[l]});const next=structuredClone(state),index=next.lines.findIndex(x=>x.id===l.id);if(index<0)next.lines.push(l);else next.lines[index]=l;const storeDefinition=!!$('pr-save_definition')?.checked,values=readJSON(PRODUCTION_KEY,{});if(storeDefinition){values[p.definition.id]=p.definition;ProductionModelCore.catalogDefinitions(values);DomainSchema.dataset({[PRODUCTION_KEY]:JSON.stringify(values)});}if(productionNeedsRecovery&&!keepCurrent())return;if(!productionStore(next))return;productionNeedsRecovery=false;if(storeDefinition&&!writeJSON(PRODUCTION_KEY,values)){toast('Строка сохранена в заказе; запись в справочник не удалась');return;}$('modal').close();render();}catch(e){productionFormError(e);}}
function productionRemove(index){productionRememberGroups();const next=structuredClone(state);next.lines.splice(index,1);if(productionStore(next))render();}
function productionToggle(index,selected){productionRememberGroups();const next=structuredClone(state);next.lines[index].production.selected=selected;if(productionStore(next))render();}
function productionPanelSaw(){productionChoices=[productionDefinitions().find(d=>d.calculation_method==='panel_saw')];productionChoose(0);}
function productionSawFields(i){const n=productionField,c=i.card||{rows:[]};return '<p class="small">Карта на весь заказ: до 12 строк, один слой толщиной 3–30 мм. Общая кромка считается один раз. Если лист уже учтён, укажите 0 листов. Измеренный чистый цикл заменяет расчётный.</p><div class="tablewrap"><table><thead><tr><th>Строка</th><th>Толщина, мм</th><th>Длина реза, м</th><th>Ходы</th><th>Листы</th><th>Чистый цикл, ч</th></tr></thead><tbody>'+Array.from({length:12},(_,j)=>'<tr><th>'+String(j+1)+'</th>'+['thickness_mm','length_m','strokes','sheets','measured_cycle_hours'].map(k=>'<td><input class="production-saw-input" id="pr-saw-'+j+'-'+k+'" aria-label="Строка '+(j+1)+': '+({thickness_mm:'толщина, мм',length_m:'длина, м',strokes:'число ходов',sheets:'число листов',measured_cycle_hours:'измеренный цикл, ч'}[k])+'" type="number" min="0" step="any" value="'+esc(c.rows[j]?.[k]??'')+'"></td>').join('')+'</tr>').join('')+'</tbody></table></div><div class="grid2">'+n('setups','Число наладок (пусто — одна при наличии резов)',c.setups,'number')+n('helper_hours','Помощник, человеко-часы',c.helper_hours??0,'number')+n('map_hours','Разработка новой карты, человеко-часы',c.map_hours??0,'number')+'</div>';}
function productionReadSaw(i){const num=id=>$(id)?.value===''?null:Number($(id)?.value),rows=[];for(let j=0;j<12;j++){const row=Object.fromEntries(['thickness_mm','length_m','strokes','sheets','measured_cycle_hours'].map(k=>[k,num('pr-saw-'+j+'-'+k)]));if(Object.values(row).every(v=>v===null))continue;rows.push(row);}i.card={rows,setups:num('pr-setups'),helper_hours:num('pr-helper_hours')??0,map_hours:num('pr-map_hours')??0};}
function productionDeck(){modal('Настил · отдельная смета монтажа',`<p>Основание и подготовка площадки относятся к строительству. Монтаж рам, лаг и доски — к монтажу на объекте. Комплексная ставка №37 2300 ₽/м² не применяется.</p><div class="tablewrap"><table><thead><tr><th>Операция</th><th>Единица</th><th>Граница</th><th></th></tr></thead><tbody>${PRODUCTION_CATALOG.deck.map((d,j)=>'<tr><td>'+esc(d.operation_or_resource)+'</td><td>'+esc(MaterialCore.unitLabel(d.unit))+'</td><td>'+esc(d.note)+'</td><td><button onclick="productionChooseDeck('+j+')">Настроить</button></td></tr>').join('')}</tbody></table></div>`);}
function productionChooseDeck(index){const item=PRODUCTION_CATALOG.deck[index];if(!item)return;const match=productionDefinitions().find(d=>d.name===item.operation_or_resource&&d.scope==='site_installation');if(match){productionChoices=[match];productionChoose(0);productionDraft.production.segment='Настил';productionEditor();return;}productionNewOperation();const d=productionDraft.production.definition;d.name=item.operation_or_resource;d.unit=item.unit;d.scope=/основан|бетон|грунт|фундамент/i.test(item.operation_or_resource)?'construction':'site_installation';d.stage=d.scope==='construction'?'construction':'installation';d.financial_basis=item.note||'Требуется обоснование ставки и затрат';d.quantity_basis=item.note||item.operation_or_resource;productionDraft.production.segment='Настил';productionEditor();}
function productionTreeHTML(r){const scopes=new Map();for(const row of r.rows.filter(x=>!x.excluded&&!x.displayOnly)){const d=row.production?.definition,scope=d?.scope||'procurement_materials';if(!scopes.has(scope))scopes.set(scope,[]);scopes.get(scope).push(row);}return [...scopes].map(([scope,rows])=>'<details open><summary>'+esc(productionScopes[scope])+' · '+productionGroupTotal(rows)+'</summary>'+rows.map(l=>'<p class="production-tree-line">'+esc(l.production?productionDisplayName(l.production.definition):l.name)+' · '+productionMoney(l.plannedCost)+'</p>').join('')+'</details>').join('');}
function productionLinesView(){productionSyncMarketStations(structuredClone(state));const r=CostEngine.calculate(state),site=page===19,rows=r.rows.filter(l=>l.production&&(site?['site_installation','construction'].includes(l.production.definition.scope):!['site_installation','construction'].includes(l.production.definition.scope))),shops=new Map();for(const l of rows){const d=productionLocation(l.production.definition);if(!shops.has(d.shop_id))shops.set(d.shop_id,new Map());const posts=shops.get(d.shop_id);if(!posts.has(d.post_id))posts.set(d.post_id,[]);posts.get(d.post_id).push(l);}
 const opened=key=>productionGroupOpen.get(key)===false?'':'open';const groups=[...shops].map(([shop,posts])=>{const shopKey=JSON.stringify([shop]),all=[...posts.values()].flat();return '<details class="production-shop-group" data-group="'+esc(shopKey)+'" '+opened(shopKey)+'><summary><span>'+esc(shop)+'</span><span class="production-subtotal">'+productionGroupTotal(all)+'</span></summary>'+[...posts].map(([post,items])=>{const key=JSON.stringify([shop,post]);return '<details class="production-post-group" data-group="'+esc(key)+'" '+opened(key)+'><summary><span>'+esc(productionPostName(post))+' <small>· '+items.length+'</small></span><span class="production-subtotal">'+productionGroupTotal(items)+'</span></summary><div class="tablewrap"><table class="production-operations"><thead><tr><th>Порядок</th><th>Операция</th><th>Объём</th><th>Себестоимость ед.</th><th>Себестоимость</th><th></th></tr></thead><tbody>'+productionOperationRows(items)+'</tbody></table></div></details>';}).join('')+'</details>';}).join('');
 $('app').innerHTML=title(site?'Монтаж и строительство':'Изготовление',site?'Работы на объекте':'Производственные операции','Раскройте цех и пост. Объём меняется прямо в строке; нормы и состав себестоимости — в карточке операции.','Себестоимость ресурсов')+steps()+`<div class="toolbar"><button class="primary" onclick="productionCatalog()">＋ Выбрать операцию</button><button onclick="productionNewOperation()">＋ Своя операция</button>${site?'<button onclick="productionDeck()">Настил</button>':''}</div><div class="production-group-list">${groups||'<div class="card"><p>Выберите операцию из справочника.</p></div>'}</div>${r.errors.length?'<div class="warning" role="alert">'+r.errors.map(esc).join('<br>')+'</div>':''}`+nextbar();}
function productionPriceReviewHTML(r){const show=v=>Number.isFinite(v)?productionMoney(v):'—',rows=[['Материалы / изделие · НДС учтён в исходных данных',r.M/r.q,null],['Материалы / партия · НДС учтён в исходных данных',null,r.M],['Изготовление / изделие · НДС учтён в исходных данных',r.manufacturingUnit,null],['Изготовление / партия · НДС учтён в исходных данных',null,r.manufacturing],['Себестоимость с НДС / изделие',r.costUnit,null],['Себестоимость партии',null,r.C],['Стоимость с прибылью / изделие',r.priceWithProfit===null?null:r.priceWithProfit/r.q,null],['Стоимость с прибылью / партия',null,r.priceWithProfit],['Прибыль до вычета налогов / изделие',r.profitBeforeTax===null?null:r.profitBeforeTax/r.q,null],['Прибыль до вычета налогов / партия',null,r.profitBeforeTax],['Прибыль после налога на прибыль (после вычета налогов) / изделие',r.profitAfterTax===null?null:r.profitAfterTax/r.q,null],['Прибыль после налога на прибыль (после вычета налогов) / партия',null,r.profitAfterTax]];return `<div class="card price-review-breakdown"><div class="cardhead"><h2>Проверка цены</h2><span class="small">НДС материалов уже учтён в исходных ценах · налог на прибыль ${dec(r.profitTax)}%</span></div><div class="tablewrap"><table><thead><tr><th>Показатель</th><th class="number">На изделие</th><th class="number">На партию · ${dec(r.q)} шт.</th></tr></thead><tbody>${rows.map(([label,unit,batch])=>`<tr><td>${label}</td><td class="number">${show(unit)}</td><td class="number">${show(batch)}</td></tr>`).join('')}</tbody></table></div></div>`;}
function productionResult(){productionSyncMarketStations(structuredClone(state));const r=CostEngine.calculate(state);$('app').innerHTML=title('Себестоимость и цена',esc(state.name),'Себестоимость складывается из ресурсов. Внутренний тариф и цена продажи рассчитаны отдельно.',r.partial?'Неполный расчёт':'Производственная модель')+steps()+`<div class="toolbar"><button class="primary" onclick="saveCalculation()">Сохранить версию</button><button onclick="quoteFromCurrent()">Создать КП</button><button onclick="saveFile()">Сохранить JSON</button><button onclick="previewInternalPDF()">Внутренний отчёт / PDF</button></div><div class="kpis"><div class="kpi featured"><div class="small">Себестоимость заказа</div><div class="big">${productionMoney(r.plannedCost)}</div></div><div class="kpi"><div class="small">Себестоимость изделия</div><div class="big">${productionMoney(r.costUnit)}</div></div><div class="kpi"><div class="small">Цена продажи заказа</div><div class="big">${productionMoney(r.total)}</div></div><div class="kpi"><div class="small">Плановая прибыль / маржа</div><div class="big">${productionMoney(r.profit)}</div><div>${r.margin===null?'Нет данных':dec(r.margin)+'%'}</div></div></div>${r.profitIncomplete?'<p class="note info">Полная себестоимость пока неизвестна: откройте операции без стоимости и укажите недостающие данные или примените исходную методику.</p>':''}${productionPriceReviewHTML(r)}<div class="card"><h2>Состав себестоимости</h2>${productionTreeHTML(r)}</div><details><summary>Расчёт цены продажи</summary><p>Сумма внутренних тарифов: ${productionMoney(r.preMarkupBase)}.</p><p>Наценка на внутренние тарифы: 40% · ${productionMoney(r.P)}.</p><p>Цена продажи = сумма внутренних тарифов × 1,40 = ${productionMoney(r.total)}. Наценка в себестоимость не входит.</p></details>${r.errors.length?'<div class="warning" role="alert"><h2>Недостающие данные</h2>'+r.errors.map(esc).join('<br>')+'</div>':''}<div class="card"><h2>Состав сложных операций</h2>${r.rows.filter(l=>!l.excluded&&!l.displayOnly&&l.components?.length>1).map(l=>'<h3>'+esc(l.production?productionDisplayName(l.production.definition):l.name)+'</h3>'+productionComponentsHTML(l.components)).join('')||'<p>Формула и параметры каждой операции доступны в её карточке.</p>'}</div>`;}
function productionLocation(d){if(d.post_id||d.source_work_id==null)return d;const matches=productionDefinitions().filter(x=>x.source_work_id===d.source_work_id&&!['inactive','out_of_scope'].includes(x.status));const first=matches[0];return first&&matches.every(x=>x.shop_id===first.shop_id&&x.post_id===first.post_id)?{...d,shop_id:first.shop_id,post_id:first.post_id}:d;}
function productionPostName(post){return PRODUCTION_CATALOG.postNames?.[post]||'Прочие работы';}
function productionDisplayName(d){let name=d.name;for(const [code,label]of Object.entries(PRODUCTION_CATALOG.postNames||{}))name=name.replace(new RegExp('\\b'+code+'\\b','g'),label);return name;}
function productionFixed(d){return d.source_work_id!=null||PRODUCTION_CATALOG.operations.some(x=>x.id===d.id);}
function productionSourceDefinitions(){const l=productionDraft,d=l.production.definition;return productionDefinitions().filter(x=>!['inactive','out_of_scope'].includes(x.status)&&(x.id===d.id||(d.source_work_id!=null&&x.source_work_id===d.source_work_id)||(l.catalogId&&x.source_record===l.catalogId)));}
function productionSourceChoices(){productionDraft=productionReadDraft();const choices=productionSourceDefinitions();modal('Исходная методика операции','<p>Ставки и нормы будут взяты из выбранной операции. Перед сохранением будет создана восстановительная копия заказа. При несовпадении единиц потребуется заново указать объём.</p>'+choices.map((d,j)=>'<div class="production-source-choice"><b>'+esc(productionDisplayName(d))+'</b><p>'+esc(MaterialCore.unitLabel(d.unit))+' · '+esc(d.shop_id)+' · '+esc(productionPostName(d.post_id))+'</p><p>Себестоимость единицы: '+productionMoney(ProductionModelCore.resourceUnitCost(d))+'</p><button onclick="productionUseSource('+j+')">Использовать эту методику</button></div>').join('')+'<button onclick="productionEditor()">Назад</button>');}
function productionUseSource(index){const d=productionSourceDefinitions()[index];if(!d)return;const old=productionDraft,p=old.production,unitChanged=!MaterialCore.sameUnit(old.unit,d.unit)||p.definition.unit_change_notice;const attributes={...p};delete attributes.inputs;delete attributes.definition;const next=ProductionModelCore.makeLine(d,old.id,{...p.inputs,quantity:unitChanged?null:p.inputs.quantity},attributes);if(d.code==='Р144.П'){next.production.inputs.package_cut=true;next.production.inputs.profiles_per_package??=null;}if(d.calculation_method==='panel_saw'){next.production.inputs={quantity:1,card:p.inputs.card||{rows:[],setups:null,helper_hours:0,map_hours:0},panel_parameters:structuredClone(PRODUCTION_CATALOG.panelSaw)};}next.productionOrder=old.productionOrder;next.catalogId=old.catalogId;productionDraft=next;productionNeedsRecovery=true;productionEditor();}
function productionAssignmentOptions(){const options={};for(const d of productionDefinitions())if(!['inactive','out_of_scope'].includes(d.status))options[d.shop_id+'|'+(d.post_id||'')]=d.shop_id+' — '+productionPostName(d.post_id);return options;}
function productionChangeAssignment(){productionDraft=productionReadDraft();productionEditor();}
function productionFormula(d){return ({direct_unit_rate:'Себестоимость единицы = трудозатраты × стоимость часа труда × множитель трудозатрат + время станка × стоимость часа станка + расходники. Себестоимость объёма = объём × себестоимость единицы.',manual:'Себестоимость объёма = объём × затраты на единицу.',external_quote:'Себестоимость объёма = объём × покупная стоимость единицы работ.',crew_cycle:'Человеко-часы = объём × работников в бригаде × цикл в минутах ÷ 60. Себестоимость = человеко-часы × стоимость часа + расходники на весь объём.',output_per_hour:'Время = объём ÷ выработка в час. Себестоимость = время × стоимость часа соответствующего ресурса.',machine_hours:'Машино-часы = объём ÷ выработка; при вводе часов используется указанное время. Себестоимость = машино-часы × стоимость часа станка.',person_hours:'Себестоимость = человеко-часы × стоимость часа труда.',setup_per_batch:'Себестоимость наладки = часы наладки × стоимость часа труда. Учитывается один раз на партию.',unique_program_prep:'Часы подготовки = длина уникальных контуров ÷ выработка. Себестоимость = часы подготовки × стоимость часа труда. Тираж повторно не применяется.',operator_support:'Часы оператора = машино-часы связанных работ поста × минут сопровождения на машино-час ÷ 60. Себестоимость = часы оператора × стоимость часа труда. Введённые интервалы занятости заменяют норму; пересечения одного сотрудника учитываются один раз.',composite:'Себестоимость комплекса = сумма предусмотренных ресурсов. При наличии дочерних позиций показывается их сумма без повторного начисления.',panel_saw:'Себестоимость карты = работа станка и пилы + наладка и подача листов + труд станочника за полный цикл + помощник + разработка карты. Измеренное время заменяет расчётное.'})[d.calculation_method]||'Себестоимость определяется составом ресурсов операции.';}
function productionCostDetails(l){const d=l.production.definition,p=d.parameters||{},values=[];const add=(name,value,unit='')=>{if(value!==undefined&&value!==null)values.push([name,dec(value)+' '+unit]);};
 if(d.calculation_method==='crew_cycle'){add('Работников в бригаде',d.cycle?.workers);add('Цикл на единицу',d.cycle?.minutes_per_unit,'мин');add('Стоимость часа труда',d.cost_model.labor_cost_per_person_hour,'₽/чел·ч');add('Расходники на единицу',d.cost_model.consumables_per_unit,'₽/'+d.unit);}
 else if(d.calculation_method==='operator_support'){const key=d.post_id==='P08'?'P08_'+(l.production.inputs.mode==='3d'?'3d':'flat'):d.post_id;if(d.post_id==='P08'&&l.production.inputs.machine_hours==null&&l.production.inputs.person_hours==null)values.push(['Сопровождение станка','По каждой операции: плоская — 30, 3D — 40 мин/маш·ч']);else add('Сопровождение станка',d.post_id==='P43'?60:PRODUCTION_CATALOG.operatorMinutes[key],'мин/маш·ч');add('Стоимость часа труда',ProductionModelCore.resourceUnitCost(d),'₽/чел·ч');}
 else if(d.calculation_method==='unique_program_prep'){add('Выработка подготовки',d.productivity?.value,d.unit+'/ч');add('Себестоимость единицы контура',ProductionModelCore.resourceUnitCost(d),'₽/'+d.unit);}
 else if(['output_per_hour','machine_hours','person_hours','setup_per_batch'].includes(d.calculation_method)){add('Выработка',d.productivity?.value,d.unit+'/ч');add('Стоимость часа труда',d.cost_model.labor_cost_per_person_hour,'₽/чел·ч');add('Стоимость часа станка',d.cost_model.machine_cost_per_machine_hour,'₽/маш·ч');}
 else if(d.calculation_method!=='panel_saw'){for(const row of ProductionModelCore.resourceBreakdown(d))values.push([row.name,(row.quantity===null?'Нет нормы':dec(row.quantity)+' '+row.unit)+' × '+productionMoney(row.rate)+' = '+productionMoney(row.amount)]);}
 if((l.production.inputs.labor_factor??1)!==1)values.push(['Множитель трудозатрат',dec(l.production.inputs.labor_factor)+' — применяется только к труду']);
 return '<p><b>Формула расчёта</b><br>'+esc(productionFormula(d))+'</p><dl class="production-parameters">'+values.map(([k,v])=>'<dt>'+esc(k)+'</dt><dd>'+esc(v)+'</dd>').join('')+'</dl>'+(d.quantity_basis?'<p class="small">'+esc(d.quantity_basis)+'</p>':'');}
function productionSawNorms(p){if(!p)return '';return '<dl class="production-parameters">'+Object.entries({setup_minutes:['Наладка','мин'],sheet_minutes:['Подача листа','мин'],meters_per_sheet:['Резов с листа','м'],machine_rate:['Работа станка','₽/ч'],setup_machine_rate:['Станок при наладке','₽/ч'],blade_per_m:['Пилы','₽/м'],operator_cost:['Стоимость часа станочника','₽/чел·ч'],helper_cost:['Стоимость часа помощника','₽/чел·ч']}).map(([k,[label,unit]])=>'<dt>'+label+'</dt><dd>'+dec(p[k])+' '+unit+'</dd>').join('')+'</dl>'+p.bands.map(b=>'<p>'+b.min_thickness_mm+'–'+b.max_thickness_mm+' мм: подача '+b.forward+' м/мин, возврат '+b.backward+' м/мин, позиционирование '+b.position_seconds+' с/ход, ход '+b.stroke_m+' м.</p>').join('');}
function productionGroupKey(l){const d=productionLocation(l.production.definition);return JSON.stringify([d.shop_id,d.post_id]);}
function productionOrdered(lines){return lines.slice().sort((a,b)=>(a.productionOrder??state.lines.findIndex(x=>x.id===a.id))-(b.productionOrder??state.lines.findIndex(x=>x.id===b.id)));}
function productionRememberGroups(){document.querySelectorAll('.production-shop-group,.production-post-group').forEach(el=>productionGroupOpen.set(el.dataset.group,el.open));}
function productionSetQuantity(id,value){try{const l=state.lines.find(x=>x.id===id);if(!l?.production)return false;const method=l.production.definition.calculation_method;if(['panel_saw','setup_per_batch'].includes(method)||l.production.parentLineId&&l.displayOnly)return false;const q=value.trim()===''?null:Number(value.replace(',','.'));if(q!==null&&(!Number.isFinite(q)||q<0))throw Error('Укажите объём не меньше нуля');const next=structuredClone(state),row=next.lines.find(x=>x.id===id);if(method==='operator_support')row.production.inputs.person_hours=q;else{row.production.inputs.quantity=q;row.qty=q;if(method==='person_hours'&&Object.hasOwn(row.production.inputs,'person_hours'))row.production.inputs.person_hours=q;if(method==='machine_hours'&&!row.production.definition.productivity)row.production.inputs.machine_hours=q;}productionRememberGroups();if(!productionStore(next))return false;render();document.getElementById('production-qty-'+id)?.focus();return true;}catch(e){toast(e.message);return false;}}
function productionReorder(id,targetId){const next=structuredClone(state),line=next.lines.find(x=>x.id===id),target=next.lines.find(x=>x.id===targetId);if(!line?.production||!target?.production||id===targetId||productionGroupKey(line)!==productionGroupKey(target))return false;const rows=productionOrdered(next.lines.filter(x=>x.production&&productionGroupKey(x)===productionGroupKey(line))),from=rows.findIndex(x=>x.id===id),to=rows.findIndex(x=>x.id===targetId);rows.splice(from,1);rows.splice(to,0,line);rows.forEach((x,j)=>{x.productionOrder=j});productionRememberGroups();if(!productionStore(next))return false;render();return true;}
function productionDragStart(event,id){productionDraggedId=id;event.dataTransfer.setData('text/plain',id);event.dataTransfer.effectAllowed='move';event.stopPropagation();}
function productionDragOver(event,id){const a=state.lines.find(x=>x.id===productionDraggedId),b=state.lines.find(x=>x.id===id);if(a?.production&&b?.production&&productionGroupKey(a)===productionGroupKey(b)){event.preventDefault();event.dataTransfer.dropEffect='move';}}
function productionDrop(event,id){event.preventDefault();productionReorder(productionDraggedId||event.dataTransfer.getData('text/plain'),id);productionDraggedId=null;}
function productionUnitBased(l){const method=l.production?.definition?.calculation_method;return l.scope==='unit'||(l.production?.definition?.scope==='product_manufacturing'&&!['setup_per_batch','unique_program_prep','operator_support','panel_saw'].includes(method));}
function productionGroupTotal(rows){const counted=rows.filter(l=>!l.excluded&&!l.displayOnly),incomplete=counted.some(l=>!Number.isFinite(l.plannedCost)),known=counted.reduce((s,l)=>s+(l.plannedCost||0),0),batch=incomplete?'Неполная · известно '+productionMoney(known):productionMoney(known),unit=incomplete?'Неполная':productionMoney(known/(state.qty||1));return 'На изделие: '+unit+' · На партию: '+batch;}
function productionUnitCost(l,rows,effectiveQuantity){const d=l.production.definition;return Number.isFinite(l.plannedCost)&&effectiveQuantity>0?l.plannedCost/effectiveQuantity:d.resource_costing?ProductionModelCore.resourceUnitCost(d):d.cost_model.unit_cost;}
function productionOperationRows(rows){return productionOrdered(rows).map(l=>{const d=l.production.definition,index=state.lines.findIndex(x=>x.id===l.id),operator=d.calculation_method==='operator_support',special=['panel_saw','setup_per_batch'].includes(d.calculation_method)||l.displayOnly,q=operator?l.production.inputs.person_hours??l.personHours:l.production.inputs.quantity,effectiveQuantity=operator?l.personHours:Number.isFinite(q)?q*(productionUnitBased(l)?state.qty:1):null,unitCost=productionUnitCost(l,rows,effectiveQuantity);
 return `<tr class="work-line" ondragover="productionDragOver(event,'${esc(l.id)}')" ondrop="productionDrop(event,'${esc(l.id)}')"><td class="production-order"><span class="drag-handle" draggable="true" ondragstart="productionDragStart(event,'${esc(l.id)}')" ondragend="productionDraggedId=null" title="Перетащить внутри поста" aria-label="Перетащить операцию">☰</span></td><td><label class="check"><input type="checkbox" aria-label="Включить ${esc(productionDisplayName(d))}" ${l.excluded?'':'checked'} onchange="productionToggle(${index},this.checked)"> ${esc(productionDisplayName(d))}</label><span class="source">${esc(productionScopes[d.scope])} · ${esc(l.production.productId)}${l.production.segment!=='Основной'?' · '+esc(l.production.segment):''}</span></td><td>${special?'<span>'+ (l.displayOnly?'Сумма состава':d.calculation_method==='panel_saw'?'По карте':dec(l.personHours||0)+' чел·ч')+'</span>':'<input class="production-quantity" id="production-qty-'+esc(l.id)+'" type="number" min="0" step="any" value="'+esc(q??'')+'" aria-label="Объём: '+esc(productionDisplayName(d))+'" onchange="productionSetQuantity(\''+esc(l.id)+'\',this.value)">'}<span class="source">${special?'':operator?'чел·ч · '+(l.production.inputs.person_hours!=null?'вручную · очистить для возврата':'автоматически'):esc(MaterialCore.unitLabel(d.unit))+(productionUnitBased(l)?' · на изделие':' · на заказ')}</span></td><td class="number">${special?'—':productionMoney(unitCost)}${operator?'<span class="source">₽/чел·ч</span>':''}</td><td class="number">${productionMoney(l.plannedCost)}${l.displayOnly?'<span class="source">Сумма детей · справочно</span>':''}</td><td><button onclick="productionEdit(${index})">Изменить</button><button class="textbutton" onclick="productionRemove(${index})">Удалить</button></td></tr>`;}).join('');}
(function(){const previousRender=render,previousEdit=editLine,previousPicker=picker,previousAdd=addCatalog,previousManual=addManual;picker=function(kind){if(state.engineVersion===ProductionModelCore.VERSION&&kind==='work')productionCatalog();else previousPicker(kind);};addCatalog=function(id){const record=CATALOG.find(x=>x.id===id);if(state.engineVersion===ProductionModelCore.VERSION&&record?.kind==='work')productionAddCatalogWork(record);else previousAdd(id);};addManual=function(kind){if(state.engineVersion===ProductionModelCore.VERSION&&kind==='work')productionNewOperation();else previousManual(kind);};editLine=function(id){const index=state.lines.findIndex(l=>l.id===id);if(index>=0&&state.lines[index].production){productionEdit(index);return;}previousEdit(id);};render=function(){previousRender();if(state.engineVersion===ProductionModelCore.VERSION){if([2,19].includes(page)){productionLinesView();$('app').insertAdjacentHTML('beforeend',productionUnmappedHTML());}if([3,4].includes(page))productionResult();}else if([0,2,19].includes(page))$('app').insertAdjacentHTML('afterbegin','<div class="note info"><b>Новая производственная модель</b><p>Цеха и посты, себестоимость из ресурсов и отдельный расчёт цены продажи.</p><button onclick="productionEnable()">Перейти на новую методику с сохранением копии</button></div>');};render();})();
